import {
  Group,
  Mesh,
  PlaneGeometry,
  BoxGeometry,
  MeshPhysicalNodeMaterial,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  DirectionalLight,
  PointLight,
} from 'three/webgpu';
import { uv, vec2, mix, texture, color as tslColor } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.name = 'filmstrip-carousel';

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? config.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#0b0b10' }, { at: 1, hex: '#12121a' }],
  };

  const items = config.textContent ?? spec.textContent ?? [];
  const headlineText = items.find((i) => i.role === 'headline')?.text ?? 'The collection';
  const bodyText = items.find((i) => i.role === 'body')?.text ?? 'Five calibres. One discipline.';
  const captionItemsRaw = items.filter((i) => i.role === 'caption').map((i) => i.text);
  const captionTexts = captionItemsRaw.length === 5
    ? captionItemsRaw
    : ['NA-01 MERIDIAN', 'NA-02 NOCTURNE', 'NA-03 SIGNAL', 'NA-04 VANTAGE', 'NA-05 ARCHIVE'];

  const disposables = [];
  const timelines = [];
  const primitiveHandles = [];

  // ---------- BACKDROP ----------
  const gStops = colors.gradientStops ?? [{ at: 0, hex: colors.background }, { at: 1, hex: '#12121a' }];
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(tslColor(gStops[0].hex), tslColor(gStops[gStops.length - 1].hex), uv().y);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(() => {
    backdropGeo.dispose();
    backdropMat.dispose();
  });

  // ---------- LIGHTS (node-local rim + accent, scene already provides ambient+key) ----------
  const rimLight = new DirectionalLight(colors.paper, 0.8);
  rimLight.position.set(-4, 2.5, -3);
  group.add(rimLight);

  const accentLight = new PointLight(colors.accent, 0.6, 6);
  accentLight.position.set(0, -0.4, 1.5);
  group.add(accentLight);
  disposables.push(() => {
    rimLight.dispose?.();
    accentLight.dispose?.();
  });

  // ---------- FILMSTRIP ----------
  const filmGroup = new Group();
  filmGroup.name = 'filmstrip-strip';
  const stripTilt = -18 * (Math.PI / 180);
  filmGroup.rotation.y = stripTilt;
  group.add(filmGroup);

  const PITCH = 1.85;
  const CARD_W = 1.6;
  const CARD_H = 1.0;
  const BEVEL = 0.025;

  const indices = [-2, -1, 0, 1, 2];
  const uvOffsets = [-0.04, -0.02, 0, 0.02, 0.04];
  const tints = [
    [1.05, 0.95, 0.85],
    [0.9, 0.95, 1.05],
    [1.0, 1.0, 1.0],
    [1.05, 0.9, 0.9],
    [0.85, 0.9, 0.95],
  ];

  const cardGeo = new PlaneGeometry(CARD_W, CARD_H);
  const frameGeo = new BoxGeometry(CARD_W + BEVEL * 2, CARD_H + BEVEL * 2, BEVEL);
  disposables.push(() => {
    cardGeo.dispose();
    frameGeo.dispose();
  });

  const cardMaterials = [];
  const focusedIndexPos = 2; // center of the 5-card array is the focused card

  indices.forEach((idx, i) => {
    const cardGroup = new Group();
    const x = idx * PITCH;
    const isFocused = i === focusedIndexPos;
    const distance = Math.abs(idx);
    const opacity = 1.0 - (distance / 2) * 0.45;
    const scale = isFocused ? 1.0 : 0.92;

    cardGroup.position.set(x, 0, 0);
    cardGroup.scale.setScalar(scale);
    cardGroup.rotation.y = isFocused ? -stripTilt : 0;

    // frame (machined ink bevel)
    const frameMat = new MeshPhysicalNodeMaterial();
    frameMat.color.set(colors.ink);
    frameMat.roughness = 0.5;
    frameMat.metalness = 0.55;
    frameMat.clearcoat = 0.2;
    frameMat.clearcoatRoughness = 0.25;
    const frameMesh = new Mesh(frameGeo, frameMat);
    frameMesh.position.z = -0.02;
    cardGroup.add(frameMesh);
    disposables.push(() => frameMat.dispose());

    // card surface
    const cardMat = new MeshPhysicalNodeMaterial();
    cardMat.colorNode = tslColor(colors.surface);
    cardMat.roughness = 0.55;
    cardMat.metalness = 0.2;
    cardMat.clearcoat = 0.15;
    cardMat.transparent = true;
    cardMat.opacity = opacity;
    const cardMesh = new Mesh(cardGeo, cardMat);
    cardGroup.add(cardMesh);
    cardMaterials.push({ mat: cardMat, offset: uvOffsets[i], tint: tints[i] });
    disposables.push(() => cardMat.dispose());

    // caption
    const captionMesh = ctx.fontAtlas.createText(captionTexts[i] ?? '', {
      fontSize: 18,
      color: colors.paper,
      align: 'center',
      letterSpacingPx: 0.08 * 18,
    });
    captionMesh.position.set(0, -1.0, 0.02);
    cardGroup.add(captionMesh);

    // focused underline bar
    if (isFocused) {
      const barGeo = new BoxGeometry(1.6, 0.035, 0.02);
      const barMat = new MeshStandardNodeMaterial();
      barMat.color.set(colors.accent);
      barMat.emissiveNode = tslColor(colors.accent).mul(1.3);
      barMat.roughness = 0.4;
      barMat.metalness = 0.1;
      const bar = new Mesh(barGeo, barMat);
      bar.position.set(0, -0.75, 0.02);
      cardGroup.add(bar);
      disposables.push(() => {
        barGeo.dispose();
        barMat.dispose();
      });
    }

    filmGroup.add(cardGroup);
  });

  // ---------- TEXTURE LOAD (single source asset, distinct tint/uv-crop per plate to avoid echo) ----------
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      cardMaterials.forEach(({ mat, offset, tint }) => {
        const uvNode = uv().add(vec2(offset, 0));
        mat.colorNode = texture(tex, uvNode).mul(tslColor([tint[0], tint[1], tint[2]]));
        mat.needsUpdate = true;
      });
    });
  }

  // ---------- PINNED HEADLINE / BODY (world space, unaffected by strip tilt) ----------
  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize: 68,
    color: colors.paper,
    align: 'left',
  });
  headline.position.set(-2.6, 1.5, 0);
  group.add(headline);

  const bodyLine = ctx.fontAtlas.createText(bodyText, {
    fontSize: 26,
    color: colors.paper,
    align: 'left',
  });
  bodyLine.position.set(-2.6, -1.5, 0);
  group.add(bodyLine);

  // ---------- CINEMATIC PRIMITIVES ----------
  const primitiveConfigs = config.cinematicPrimitives ?? [];
  primitiveConfigs.forEach((p) => {
    const fn = ctx.primitives[p.name];
    if (typeof fn === 'function') {
      const target = p.name === 'parallax-scroll' ? filmGroup : group;
      const handle = fn(target, p.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  });

  // ---------- ENTRANCE MOTION (weighted-settle) ----------
  group.scale.setScalar(0.98);
  filmGroup.position.y = 0.3;
  const tl = gsap.timeline();
  tl.to(group.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power2.out' })
    .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.4, ease: 'power4.out' })
    .to(filmGroup.position, { y: 0, duration: 0.9, ease: 'power4.out' }, 0);
  timelines.push(tl);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    primitiveHandles.forEach((h) => h?.cleanup?.());
    disposables.forEach((d) => d());
  };

  return group;
}
